SET NAMES utf8mb4;

UPDATE `pages` SET
    `banner_title` = 'About Blossom',
    `banner_heading` = 'Beauty and nail care in the heart of Gorlice',
    `banner_text` = 'Blossom Ewa Mazur is a small salon on Piekarska Street, just above the 5.10.15 store. Manicure and nail art are our speciality, with hair, skin, makeup and waxing alongside them.',
    `banner_background` = '736b46f9131f620f5cd3ce577e49fa9f.jpg',
    `meta_description` = 'Blossom Ewa Mazur is a small manicure and nail art salon on Piekarska Street in Gorlice, with hair, skin, makeup and waxing alongside.'
WHERE `page_id` = 2;

DELETE FROM `web_page_sections` WHERE `page_id` = 2 AND `section_key` NOT IN ('approach', 'nails_first', 'products', 'team', 'location', 'cta');

